# Target columns of ZAM IDs from here on (see 0022_zamid_triggers_and_claim).
COLUMNS = ("item_id", "location_id", "url", "unique_item_id")

# ZAM-local members may record and move unique items and print the inventory.
# Removing unique items from the inventory, changing their owner and the
# internal details stay with the admins.
GRANTS = [
    ("uniqueitem", "add_uniqueitem", "Can add unique item"),
    ("uniqueitem", "change_uniqueitem", "Can change unique item"),
    ("location", "print_inventory", "Can print the inventory of locations"),
]


def mark_priced_items_for_sale(apps, schema_editor):
    # Everything else stays undecided: many bulk items are for the ZAM's own use.
    Item = apps.get_model("inventory", "Item")
    Item.objects.using(schema_editor.connection.alias).filter(sale_price__isnull=False).update(for_sale=True)


def move_documents(apps, schema_editor):
    """Existing files move to unguessable document folders; old copies go once this has committed."""
    alias = schema_editor.connection.alias
    moved = []
    for document in apps.get_model("inventory", "ItemFile").objects.using(alias).exclude(file__startswith="documents/"):
        old = document.file.name
        if not old or not default_storage.exists(old):
            continue
        # Old names were "<folder>/<ISO timestamp>_<file name>".
        filename = re.sub(r"^\d{4}-\d\d-\d\dT[\d:.]+_", "", old.rsplit("/", 1)[-1])
        with default_storage.open(old, "rb") as content:
            document.file = default_storage.save(get_document_upload_path(document, filename), content)
        document.save(update_fields=["file"])
        moved.append(old)
    transaction.on_commit(lambda: [default_storage.delete(name) for name in moved], using=alias)


def grant_to_local_group(apps, schema_editor):
    alias = schema_editor.connection.alias
    group, _ = apps.get_model("auth", "Group").objects.using(alias).get_or_create(name="ZAM-local")
    content_types = apps.get_model("contenttypes", "ContentType").objects.using(alias)
    permissions = apps.get_model("auth", "Permission").objects.using(alias)
    # Permissions are normally created after migrations; create these explicitly.
    for model, codename, name in GRANTS:
        content_type, _ = content_types.get_or_create(app_label="inventory", model=model)
        permission, _ = permissions.get_or_create(
            content_type=content_type, codename=codename, defaults={"name": name},
        )
        group.permissions.add(permission)


def install_triggers(apps, schema_editor):
    # The triggers name every target column, and SQLite drops them when the
    # constraint changes above rebuild the table.
    triggers.install(schema_editor, COLUMNS)


def uninstall_triggers(apps, schema_editor):
    triggers.uninstall(schema_editor)


def install_previous_triggers(apps, schema_editor):
    triggers.install(schema_editor, ("item_id", "location_id", "url"))


